+async function getOrdersForCustomer(db, customerId, fulfillmentStatus) {
+  // New filter: let callers narrow to a specific fulfillment status.
+  return db.query(
+    'SELECT * FROM orders WHERE customer_id = $1 AND fulfillment_status = $2 ORDER BY placed_at DESC',
+    [customerId, fulfillmentStatus],
+  );
 }

 module.exports = { getOrdersForCustomer };

