@@ -1,5 +1,15 @@
-async function getOrdersByStatus(db, status) {
-  return db.query('SELECT id, total_cents FROM orders WHERE status = $1', [status]);
+const SORTABLE_COLUMNS = new Set(['placed_at', 'total_cents', 'status']);
+
+async function getOrdersByStatus(db, status, sortColumn) {
+  // Allow the caller to choose the sort column for the admin orders table,
+  // restricted to a fixed allowlist so the identifier is never user-supplied text.
+  if (!SORTABLE_COLUMNS.has(sortColumn)) {
+    throw new Error(`unsupported sort column: ${sortColumn}`);
+  }
+  return db.query(
+    `SELECT id, total_cents FROM orders WHERE status = $1 ORDER BY ${sortColumn}`,
+    [status],
+  );
 }

 module.exports = { getOrdersByStatus };

@@ -1,5 +1,10 @@
-async function generateQuarterlyComplianceReport(db) {
-  return db.query('SELECT * FROM orders WHERE flagged_for_review = true');
+// Runs once per quarter from a manually-triggered admin cron job, never on
+// a user-facing request path. Reads the full flagged set for compliance sign-off.
+async function generateQuarterlyComplianceReport(db, quarterStart, quarterEnd) {
+  return db.query(
+    'SELECT * FROM orders WHERE flagged_for_review = true AND placed_at BETWEEN $1 AND $2',
+    [quarterStart, quarterEnd],
+  );
 }

 module.exports = { generateQuarterlyComplianceReport };
